src = open("test_reduce.py").read()
old = '''def solve_sat(instance) -> bool:
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product((False, True), repeat=m):
        ok = True
        for clause in clauses:
            if not any((bits[abs(l) - 1] if l > 0 else not bits[abs(l) - 1])
                       for l in clause):
                ok = False
                break
        if ok:
            return True
    return False
'''
new = '''def solve_sat(instance) -> bool:
    """DPLL with unit propagation (exact, exponential worst case)."""
    m = instance["num_vars"]
    clauses = [list(c) for c in instance["clauses"]]

    def simplify(clauses, assignment):
        # returns (new_clauses, ok) with assignment applied
        out = []
        for clause in clauses:
            new_clause = []
            satisfied = False
            for l in clause:
                v = abs(l)
                if v in assignment:
                    if assignment[v] == (l > 0):
                        satisfied = True
                        break
                else:
                    new_clause.append(l)
            if satisfied:
                continue
            out.append(new_clause)
        return out

    def dpll(clauses, assignment):
        while True:
            # unit propagation
            unit = None
            for clause in clauses:
                if len(clause) == 0:
                    return False
                if len(clause) == 1:
                    unit = clause[0]
                    break
            if unit is None:
                break
            assignment = dict(assignment)
            assignment[abs(unit)] = unit > 0
            clauses = simplify(clauses, {abs(unit): unit > 0})
        if not clauses:
            return True
        # choose a variable
        var = abs(clauses[0][0])
        for value in (True, False):
            new_assign = dict(assignment)
            new_assign[var] = value
            if dpll(simplify(clauses, {var: value}), new_assign):
                return True
        return False

    return dpll(clauses, {})
'''
